function normalizeCanonicalUrl(value) {
  if (!value) return "";
  let parsed;
  try {
    parsed = new URL(String(value).trim(), "https://www.onlinejobs.ph");
  } catch {
    return "";
  }
  if (!["http:", "https:"].includes(parsed.protocol)) return "";
  if (parsed.username || parsed.password || (parsed.port && parsed.port !== "443")) return "";
  parsed.protocol = "https:";
  parsed.hostname = parsed.hostname.toLowerCase();
  if (parsed.hostname === "www.onlinejobs.ph") parsed.hostname = "onlinejobs.ph";
  if (parsed.hostname !== "onlinejobs.ph") return "";
  parsed.hash = "";
  parsed.search = "";
  parsed.pathname = parsed.pathname.replace(/\/+/g, "/").replace(/\/$/, "");
  if (!/^\/jobseekers\/job\/[^/]+$/i.test(parsed.pathname)) return "";
  parsed.port = "";
  return parsed.toString();
}

function extractOnlineJobsId(url) {
  const canonicalUrl = normalizeCanonicalUrl(url);
  if (!canonicalUrl) return "";
  const match = canonicalUrl.match(/\/jobseekers\/job\/[^/]*?(\d+)$/i);
  return match?.[1] ?? "";
}

function canonicalJobId(record) {
  const source = String(record.source || "onlinejobs.ph").trim().toLowerCase();
  const sourceJobId = String(record.source_job_id || extractOnlineJobsId(record.canonical_url || record.job_url) || "").trim();
  if (sourceJobId) return `${source}:${sourceJobId}`;
  const canonicalUrl = normalizeCanonicalUrl(record.canonical_url || record.job_url);
  if (!canonicalUrl) return "";
  let hash = 2166136261;
  for (let index = 0; index < canonicalUrl.length; index += 1) {
    hash ^= canonicalUrl.charCodeAt(index);
    hash = Math.imul(hash, 16777619);
  }
  const digest = (hash >>> 0).toString(16).padStart(8, "0");
  return `${source}:url:${digest}`;
}

function stateGuard(record) {
  const canonicalId = String(record.canonical_job_id || canonicalJobId(record) || "");
  if (!canonicalId) return "";
  const state = [
    canonicalId,
    String(record.pipeline_status || ""),
    String(record.application_decision || ""),
    String(record.first_reviewed_at || ""),
    String(record.apply_points_used || ""),
    String(record.application_message_strategy || ""),
    String(record.outcome || ""),
    JSON.stringify(Array.isArray(record.outcome_events) ? record.outcome_events : [])
  ].join("\u001f");
  let hash = 2166136261;
  for (let index = 0; index < state.length; index += 1) {
    hash ^= state.charCodeAt(index);
    hash = Math.imul(hash, 16777619);
  }
  return `${canonicalId}|${(hash >>> 0).toString(16).padStart(8, "0")}`;
}

function rankingPriorityValue(record) {
  if (
    typeof record?.opportunity_score === "number" &&
    Number.isFinite(record.opportunity_score)
  ) {
    return {
      value: record.opportunity_score,
      source: "opportunity_score"
    };
  }
  if (typeof record?.match_score === "number" && Number.isFinite(record.match_score)) {
    return {
      value: record.match_score,
      source: "legacy_match_score"
    };
  }
  return { value: 0, source: "missing" };
}

function compareRankingPriority(left, right) {
  const scoreOrder =
    rankingPriorityValue(right).value - rankingPriorityValue(left).value;
  if (scoreOrder !== 0) return scoreOrder;
  const confidenceOrder =
    ({ high: 3, medium: 2, low: 1 }[right.ranking_confidence] ?? 0) -
    ({ high: 3, medium: 2, low: 1 }[left.ranking_confidence] ?? 0);
  if (confidenceOrder !== 0) return confidenceOrder;
  const timestamp = (value) => {
    const parsed = Date.parse(value || "");
    return Number.isFinite(parsed) ? parsed : Number.NEGATIVE_INFINITY;
  };
  const rightPosted = timestamp(right.posted_at);
  const leftPosted = timestamp(left.posted_at);
  if (rightPosted !== leftPosted) return rightPosted - leftPosted;
  const rightCreated = timestamp(right.created_at);
  const leftCreated = timestamp(left.created_at);
  if (rightCreated !== leftCreated) return rightCreated - leftCreated;
  return String(left.canonical_job_id || "").localeCompare(
    String(right.canonical_job_id || "")
  );
}

function parseList(value) {
  if (Array.isArray(value)) return value.filter(Boolean);
  if (!value) return [];
  try {
    const parsed = JSON.parse(value);
    if (Array.isArray(parsed)) return parsed.filter(Boolean);
  } catch {
    // Legacy sheets may use comma-separated values.
  }
  return String(value)
    .split(",")
    .map((part) => part.trim())
    .filter(Boolean);
}

function parseJsonArray(value) {
  if (Array.isArray(value)) return value;
  if (!value) return [];
  try {
    const parsed = JSON.parse(value);
    return Array.isArray(parsed) ? parsed : value;
  } catch {
    return value;
  }
}

function normalizeRuleValue(value, rule) {
  if (!rule || value === "" || value === undefined || value === null) return value ?? "";
  if (rule.type === "number" || rule.type === "integer") {
    const numeric = Number(value);
    return Number.isFinite(numeric) ? numeric : value;
  }
  if (rule.type === "string") return String(value).trim();
  return value;
}

function mergeOutcomeEvents(...collections) {
  const events = new Map();
  for (const collection of collections) {
    if (!Array.isArray(collection)) continue;
    for (const event of collection) {
      if (!event || typeof event !== "object" || Array.isArray(event)) continue;
      const id = String(event.id || "").trim();
      if (!id || events.has(id)) continue;
      events.set(id, { ...event, id });
    }
  }
  const timestamp = (value) => {
    const parsed = Date.parse(value || "");
    return Number.isFinite(parsed) ? parsed : Number.POSITIVE_INFINITY;
  };
  return [...events.values()].sort(
    (left, right) =>
      timestamp(left.at) - timestamp(right.at) ||
      String(left.id).localeCompare(String(right.id))
  );
}

function normalizeLegacyRecord(input, schema, now = new Date().toISOString()) {
  const record = { ...input };
  for (const [legacy, canonical] of Object.entries(schema.legacy_header_mapping ?? {})) {
    if (record[canonical] === undefined && record[legacy] !== undefined) {
      record[canonical] = record[legacy];
    }
  }

  const legacyStatus = String(record.pipeline_status || "").trim().toLowerCase();
  record.pipeline_status =
    schema.legacy_status_mapping?.[legacyStatus] ||
    (schema.pipeline_statuses.includes(legacyStatus) ? legacyStatus : "discovered");
  record.source = String(record.source || "onlinejobs.ph").trim().toLowerCase();
  record.canonical_url = normalizeCanonicalUrl(record.canonical_url || record.job_url);
  record.source_job_id = String(record.source_job_id || extractOnlineJobsId(record.canonical_url) || "");
  record.canonical_job_id = String(record.canonical_job_id || canonicalJobId(record));
  for (const field of schema.string_list_fields ?? ["search_queries", "role_families"]) {
    record[field] = parseList(record[field]);
  }
  for (const field of schema.json_array_fields ?? []) {
    record[field] = parseJsonArray(record[field]);
  }
  for (const [field, rule] of Object.entries(schema.field_rules ?? {})) {
    record[field] = normalizeRuleValue(record[field], rule);
  }
  record.attempt_count = Number.isFinite(Number(record.attempt_count))
    ? Number(record.attempt_count)
    : 0;
  record.alert_attempt_count = Number.isFinite(Number(record.alert_attempt_count))
    ? Number(record.alert_attempt_count)
    : 0;
  record.created_at = record.created_at || now;
  record.updated_at = record.updated_at || now;
  record.source_availability = record.source_availability || "unknown";
  record.profile_version = record.profile_version || "legacy/unknown";
  record.message_profile_version =
    record.message_profile_version ||
    (record.generated_message ? "legacy/unknown" : "");
  record.application_decision =
    record.application_decision ||
    (record.pipeline_status === "applied" ? "applied" : record.pipeline_status === "skipped" ? "skipped" : "");
  record.outcome = record.outcome || "";
  record.manual_action = record.manual_action || "";
  record.state_guard = record.state_guard || stateGuard(record);
  return record;
}

function validateRecordContract(record, schema) {
  const errors = [];
  const fields = new Set(schema?.fields ?? []);
  for (const [field, rule] of Object.entries(schema?.field_rules ?? {})) {
    if (!fields.has(field)) {
      errors.push(`field rule references unknown field: ${field}`);
      continue;
    }
    const value = record?.[field];
    const missing = value === "" || value === undefined || value === null;
    if (missing) {
      if (rule.nullable === false) errors.push(`${field} is required`);
      continue;
    }
    if (rule.type === "enum") {
      if (!rule.values?.includes(value)) errors.push(`${field} has unsupported value: ${value}`);
      continue;
    }
    if (rule.type === "string") {
      if (typeof value !== "string") {
        errors.push(`${field} must be a string`);
        continue;
      }
      if (
        rule.maximum_length !== undefined &&
        value.length > rule.maximum_length
      ) {
        errors.push(`${field} exceeds its maximum length`);
      }
      if (rule.pattern && !new RegExp(rule.pattern).test(value)) {
        errors.push(`${field} has an unsupported format`);
      }
      continue;
    }
    const numeric = typeof value === "number" ? value : Number.NaN;
    if (!Number.isFinite(numeric)) {
      errors.push(`${field} must be a ${rule.type}`);
      continue;
    }
    if (rule.type === "integer" && !Number.isInteger(numeric)) {
      errors.push(`${field} must be an integer`);
    }
    if (rule.minimum !== undefined && numeric < rule.minimum) {
      errors.push(`${field} must be at least ${rule.minimum}`);
    }
    if (rule.maximum !== undefined && numeric > rule.maximum) {
      errors.push(`${field} must be at most ${rule.maximum}`);
    }
  }
  for (const field of schema?.string_list_fields ?? []) {
    const value = record?.[field];
    if (value !== undefined && !Array.isArray(value)) errors.push(`${field} must be an array`);
  }
  for (const field of schema?.json_array_fields ?? []) {
    const value = record?.[field];
    if (value !== undefined && !Array.isArray(value)) errors.push(`${field} must be a JSON array`);
  }
  if (Array.isArray(record?.outcome_events)) {
    const seen = new Set();
    const allowedTypes = new Set([
      "no_response",
      "replied",
      "interview",
      "offer",
      "rejected",
      "correction"
    ]);
    for (const [index, event] of record.outcome_events.entries()) {
      if (!event || typeof event !== "object" || Array.isArray(event)) {
        errors.push(`outcome_events[${index}] must be an object`);
        continue;
      }
      const id = String(event.id || "");
      if (!id || id.length > 256) {
        errors.push(`outcome_events[${index}].id is invalid`);
      } else if (seen.has(id)) {
        errors.push(`outcome_events contains duplicate id: ${id}`);
      } else {
        seen.add(id);
      }
      if (!allowedTypes.has(event.type)) {
        errors.push(`outcome_events[${index}].type is invalid`);
      }
      if (
        typeof event.at !== "string" ||
        !Number.isFinite(Date.parse(event.at))
      ) {
        errors.push(`outcome_events[${index}].at is invalid`);
      }
      for (const field of ["previous_outcome", "corrected_outcome"]) {
        if (
          event[field] !== undefined &&
          !["", "no_response", "replied", "interview", "offer", "rejected"].includes(
            event[field]
          )
        ) {
          errors.push(`outcome_events[${index}].${field} is invalid`);
        }
      }
    }
  }
  for (const field of schema?.timestamp_fields ?? []) {
    const value = record?.[field];
    if (value === "" || value === undefined || value === null) continue;
    if (typeof value !== "string" || !Number.isFinite(Date.parse(value))) {
      errors.push(`${field} must be a valid timestamp`);
    }
  }
  return errors;
}

function applyValidatedRecordUpdate(record, updates, schema) {
  const candidate = { ...record, ...updates };
  const errors = validateRecordContract(candidate, schema);
  if (errors.length > 0) {
    throw new Error(`Invalid record update: ${errors.join("; ")}`);
  }
  return candidate;
}

function validatePipelineSchema(schema) {
  const errors = [];
  if (schema?.schema_version !== 1) errors.push("schema_version must be 1");
  if (!Array.isArray(schema?.fields) || schema.fields.length === 0) errors.push("fields are required");
  if (!Array.isArray(schema?.pipeline_statuses) || schema.pipeline_statuses.length === 0) {
    errors.push("pipeline_statuses are required");
  }
  const duplicateFields = schema?.fields?.filter((field, index, all) => all.indexOf(field) !== index) ?? [];
  if (duplicateFields.length > 0) errors.push(`duplicate fields: ${[...new Set(duplicateFields)].join(", ")}`);
  const fields = new Set(schema?.fields ?? []);
  for (const collection of ["string_list_fields", "json_array_fields", "timestamp_fields"]) {
    if (!Array.isArray(schema?.[collection])) {
      errors.push(`${collection} must be an array`);
      continue;
    }
    for (const field of schema[collection]) {
      if (!fields.has(field)) errors.push(`${collection} references unknown field: ${field}`);
    }
  }
  for (const [field, rule] of Object.entries(schema?.field_rules ?? {})) {
    if (!fields.has(field)) errors.push(`field rule references unknown field: ${field}`);
    if (!["number", "integer", "enum", "string"].includes(rule?.type)) {
      errors.push(`field rule has unsupported type for ${field}`);
    }
    if (rule?.type === "enum" && (!Array.isArray(rule.values) || rule.values.length === 0)) {
      errors.push(`enum field rule requires values for ${field}`);
    }
    if (rule?.type === "string" && rule.pattern) {
      try {
        new RegExp(rule.pattern);
      } catch {
        errors.push(`string field rule has invalid pattern for ${field}`);
      }
    }
  }

  const statuses = new Set(schema?.pipeline_statuses ?? []);
  for (const [from, destinations] of Object.entries(schema?.transitions ?? {})) {
    if (!statuses.has(from)) errors.push(`transition source is not a status: ${from}`);
    for (const to of destinations) {
      if (!statuses.has(to)) errors.push(`transition destination is not a status: ${to}`);
    }
  }
  for (const status of statuses) {
    if (!(status in (schema?.transitions ?? {}))) errors.push(`missing transitions for status: ${status}`);
  }
  return errors;
}

function canTransition(schema, from, to) {
  return (schema.transitions?.[from] ?? []).includes(to);
}

function transitionRecord(record, to, schema, now = new Date().toISOString()) {
  const from = record.pipeline_status;
  if (!canTransition(schema, from, to)) {
    throw new Error(`Invalid pipeline transition: ${from} -> ${to}`);
  }
  const next = {
    ...record,
    pipeline_status: to,
    updated_at: now
  };
  return { ...next, state_guard: stateGuard(next) };
}

function isStaleClaim(record, nowMs, leaseMs) {
  if (!record.processing_token || !record.processing_started_at) return true;
  const startedAt = Date.parse(record.processing_started_at);
  return !Number.isFinite(startedAt) || nowMs - startedAt >= leaseMs;
}

function claimRecord(record, { stage, token, now, leaseMs }) {
  const nowMs = Date.parse(now);
  if (!stage || !token || !Number.isFinite(nowMs) || !Number.isFinite(leaseMs) || leaseMs < 1) {
    throw new Error("stage, token, valid now, and positive leaseMs are required");
  }
  if (record.processing_token && !isStaleClaim(record, nowMs, leaseMs)) {
    return { claimed: false, record };
  }
  return {
    claimed: true,
    record: {
      ...record,
      processing_stage: stage,
      processing_token: token,
      processing_started_at: now,
      updated_at: now
    }
  };
}

function releaseClaim(record, token, now = new Date().toISOString()) {
  if (record.processing_token && record.processing_token !== token) {
    throw new Error("processing token mismatch");
  }
  const next = {
    ...record,
    processing_stage: "",
    processing_token: "",
    processing_started_at: "",
    updated_at: now
  };
  return { ...next, state_guard: stateGuard(next) };
}

function createProcessingClaim(record, executionId, now, leaseMs) {
  const token = `${executionId}:${record.canonical_job_id}:${record.work_stage}`;
  return {
    canonical_job_id: record.canonical_job_id,
    processing_stage: record.work_stage,
    processing_token: token,
    created_at: now,
    expires_at: new Date(Date.parse(now) + leaseMs).toISOString()
  };
}

function chooseWinningClaims(proposedRecords, allClaims, now = new Date().toISOString()) {
  const nowMs = Date.parse(now);
  const validClaims = allClaims.filter((claim) => {
    const createdAt = Date.parse(claim.created_at);
    const expiresAt = Date.parse(claim.expires_at);
    return claim.canonical_job_id && claim.processing_stage && claim.processing_token &&
      Number.isFinite(createdAt) && Number.isFinite(expiresAt) && expiresAt > nowMs;
  });
  const winners = new Map();
  for (const claim of validClaims) {
    const key = `${claim.canonical_job_id}:${claim.processing_stage}`;
    const current = winners.get(key);
    const claimRow = Number(claim.row_number);
    const currentRow = Number(current?.row_number);
    const bothHaveRows = Number.isFinite(claimRow) && Number.isFinite(currentRow);
    if (
      !current ||
      (bothHaveRows && claimRow < currentRow) ||
      (!bothHaveRows && Date.parse(claim.created_at) < Date.parse(current.created_at)) ||
      (!bothHaveRows &&
        claim.created_at === current.created_at &&
        claim.processing_token < current.processing_token)
    ) {
      winners.set(key, claim);
    }
  }
  return proposedRecords.filter((record) => {
    const key = `${record.canonical_job_id}:${record.work_stage}`;
    return winners.get(key)?.processing_token === record.processing_token;
  });
}


const ALLOWED_CHANNELS = ["slack"];
const ENVIRONMENT_NAME = /^[A-Z][A-Z0-9_]{2,63}$/;

function cleanText(value, maximum = 500) {
  return String(value || "")
    .normalize("NFKC")
    .replace(/[\u200b-\u200d\u2060\ufeff]/gi, "")
    .replace(/[\u0000-\u001f\u007f-\u009f]/g, " ")
    .replace(/\s+/g, " ")
    .replace(
      /(api[_-]?key|token|authorization|password|secret)\s*[:=]\s*\S+/gi,
      "$1=[redacted]"
    )
    .trim()
    .slice(0, maximum);
}

function alertIdempotencyKey(record, policy) {
  const canonicalId = String(record?.canonical_job_id || "").trim();
  return canonicalId && policy?.policy_version
    ? `${canonicalId}|${policy.policy_version}`
    : "";
}

function validateAlertPolicy(policy) {
  const errors = [];
  if (!policy || typeof policy !== "object" || Array.isArray(policy)) {
    return ["alert policy must be an object"];
  }
  if (policy.schema_version !== 1) errors.push("alert policy schema_version must be 1");
  if (!/^\d{4}-\d{2}-\d{2}\/v\d+$/.test(policy.policy_version ?? "")) {
    errors.push("alert policy_version must use YYYY-MM-DD/vN");
  }
  if (!ALLOWED_CHANNELS.includes(policy.channel)) {
    errors.push("alert channel is unsupported");
  }
  for (const field of [
    "schedule_minutes",
    "per_run_cap",
    "claim_lease_ms",
    "provider_timeout_ms",
    "maximum_message_characters",
    "maximum_action_url_characters",
    "summary_item_characters"
  ]) {
    if (!Number.isInteger(policy[field]) || policy[field] < 1) {
      errors.push(`${field} must be a positive integer`);
    }
  }
  if (
    !Number.isInteger(policy.retry?.max_attempts) ||
    policy.retry.max_attempts < 1 ||
    !Number.isInteger(policy.retry?.backoff_ms) ||
    policy.retry.backoff_ms < 1
  ) {
    errors.push("alert retry bounds are invalid");
  }
  if (policy.retry?.ambiguous_timeout_terminal !== true) {
    errors.push("Slack ambiguous timeouts must be terminal to prevent blind duplicates");
  }
  if (
    Number.isInteger(policy.maximum_message_characters) &&
    Number.isInteger(policy.maximum_action_url_characters) &&
    policy.maximum_message_characters <
      policy.maximum_action_url_characters * 3 + 1000
  ) {
    errors.push(
      "maximum_message_characters must preserve three actions and required context"
    );
  }
  for (const field of [
    "maximum_age_days",
    "minimum_qualification_score",
    "minimum_opportunity_score",
    "maximum_major_gaps"
  ]) {
    const value = policy.eligibility?.[field];
    if (!Number.isFinite(value) || value < 0) {
      errors.push(`eligibility.${field} must be non-negative`);
    }
  }
  for (const field of [
    "minimum_qualification_score",
    "minimum_opportunity_score"
  ]) {
    if (policy.eligibility?.[field] > 100) {
      errors.push(`eligibility.${field} must not exceed 100`);
    }
  }
  if (
    !Array.isArray(policy.eligibility?.allowed_confidence) ||
    policy.eligibility.allowed_confidence.length === 0 ||
    policy.eligibility.allowed_confidence.some(
      (value) => !["high", "medium", "low"].includes(value)
    )
  ) {
    errors.push("eligibility.allowed_confidence is invalid");
  }
  if (policy.eligibility?.required_pack_status !== "ready") {
    errors.push("alert eligibility must require a ready pack");
  }
  for (const [field, value] of Object.entries(policy.environment ?? {})) {
    if (
      !["provider_webhook_url", "review_url"].includes(field) ||
      !ENVIRONMENT_NAME.test(value ?? "")
    ) {
      errors.push(`invalid alert environment reference: ${field}`);
    }
  }
  if (Object.keys(policy.environment ?? {}).length !== 2) {
    errors.push("provider_webhook_url and review_url environment references are required");
  }
  return errors;
}

function validateAlertProviderConfiguration(
  { webhookUrl, reviewUrl },
  policy
) {
  const errors = [];
  let webhook;
  try {
    webhook = new URL(webhookUrl);
  } catch {
    errors.push("provider webhook URL is missing or invalid");
  }
  if (
    webhook &&
    (webhook.protocol !== "https:" ||
      !["hooks.slack.com", "hooks.slack-gov.com"].includes(webhook.hostname) ||
      webhookUrl.length > policy.maximum_action_url_characters)
  ) {
    errors.push(
      "provider webhook URL must use an approved bounded Slack HTTPS host"
    );
  }
  let review;
  try {
    review = new URL(reviewUrl);
  } catch {
    errors.push("review URL is missing or invalid");
  }
  if (
    review &&
    (review.protocol !== "https:" ||
      review.username ||
      review.password ||
      reviewUrl.length > policy.maximum_action_url_characters)
  ) {
    errors.push("review URL must use bounded credential-free HTTPS");
  }
  if (policy.channel !== "slack") errors.push("provider channel is unsupported");
  return errors;
}

function scoreKnown(value) {
  return typeof value === "number" && Number.isFinite(value);
}

function evaluateAlertEligibility(
  record,
  policy,
  now = new Date().toISOString()
) {
  const reasons = [];
  if (!record?.canonical_job_id) reasons.push("missing_identity");
  const sourceUrl = normalizeCanonicalUrl(record?.canonical_url);
  if (
    !sourceUrl ||
    sourceUrl.length > policy.maximum_action_url_characters
  ) {
    reasons.push("source_url_invalid");
  }
  if (record?.pipeline_status !== "ready") reasons.push("lifecycle_not_ready");
  if (record?.application_decision) reasons.push("application_already_decided");
  if (record?.source_availability === "unavailable") reasons.push("source_unavailable");
  if (record?.application_pack_status !== policy.eligibility.required_pack_status) {
    reasons.push("pack_not_ready");
  }
  if (
    !scoreKnown(record?.qualification_score) ||
    record.qualification_score < policy.eligibility.minimum_qualification_score
  ) {
    reasons.push("qualification_below_threshold");
  }
  if (
    !scoreKnown(record?.opportunity_score) ||
    record.opportunity_score < policy.eligibility.minimum_opportunity_score
  ) {
    reasons.push("opportunity_below_threshold");
  }
  if (!policy.eligibility.allowed_confidence.includes(record?.ranking_confidence)) {
    reasons.push("confidence_not_allowed");
  }
  const majorGaps = (Array.isArray(record?.requirement_gap_details)
    ? record.requirement_gap_details
    : []
  ).filter((gap) => ["hard", "ambiguous"].includes(gap?.classification));
  if (majorGaps.length > policy.eligibility.maximum_major_gaps) {
    reasons.push("major_gap_limit_exceeded");
  }
  const nowMs = Date.parse(now);
  const postedMs = Date.parse(record?.posted_at || "");
  const postingAgeDays =
    Number.isFinite(nowMs) && Number.isFinite(postedMs) && postedMs <= nowMs
      ? (nowMs - postedMs) / (24 * 60 * 60 * 1000)
      : undefined;
  if (
    postingAgeDays === undefined ||
    postingAgeDays > policy.eligibility.maximum_age_days
  ) {
    reasons.push(
      record?.posted_at ? "posting_timestamp_invalid" : "posting_timestamp_missing"
    );
  }
  return {
    eligible: reasons.length === 0,
    reasons,
    posting_age_days: postingAgeDays
  };
}

function queueAlertState(
  record,
  policy,
  now = new Date().toISOString()
) {
  const eligibility = evaluateAlertEligibility(record, policy, now);
  const key = alertIdempotencyKey(record, policy);
  if (
    record.alert_status === "sent" &&
    record.alert_idempotency_key === key
  ) {
    return record;
  }
  if (record.source_availability === "unavailable") {
    return {
      ...record,
      alert_status: "suppressed",
      alert_channel: policy.channel,
      alert_policy_version: policy.policy_version,
      alert_idempotency_key: key,
      alert_suppressed_reason: "source_unavailable",
      alert_next_retry_at: "",
      updated_at: now
    };
  }
  if (!eligibility.eligible) {
    return {
      ...record,
      alert_status: "not_eligible",
      alert_channel: policy.channel,
      alert_policy_version: policy.policy_version,
      alert_idempotency_key: key,
      alert_suppressed_reason: eligibility.reasons.join(","),
      alert_next_retry_at: "",
      updated_at: now
    };
  }
  if (
    record.alert_idempotency_key === key &&
    ["pending", "sending", "retryable_failure", "terminal_failure"].includes(
      record.alert_status
    )
  ) {
    return record;
  }
  return {
    ...record,
    alert_status: "pending",
    alert_channel: policy.channel,
    alert_policy_version: policy.policy_version,
    alert_idempotency_key: key,
    alert_attempt_count: 0,
    alert_last_attempt_at: "",
    alert_next_retry_at: now,
    alert_sent_at: "",
    alert_provider_reference: "",
    alert_error_category: "",
    alert_error_summary: "",
    alert_suppressed_reason: "",
    updated_at: now
  };
}

function retryDue(record, now) {
  if (!record.alert_next_retry_at) return true;
  const retryAt = Date.parse(record.alert_next_retry_at);
  return !Number.isFinite(retryAt) || retryAt <= Date.parse(now);
}

function selectAlertCandidates(
  rawRows,
  schema,
  policy,
  now = new Date().toISOString()
) {
  const selected = [];
  for (const raw of rawRows) {
    const record = normalizeLegacyRecord(raw, schema, now);
    if (record.alert_status === "sending") {
      if (
        !isStaleClaim(record, Date.parse(now), policy.claim_lease_ms)
      ) {
        continue;
      }
      selected.push({
        ...record,
        alert_status: "terminal_failure",
        alert_next_retry_at: "",
        alert_error_category: "ambiguous_delivery",
        alert_error_summary:
          "Delivery began but its final acknowledgement was not persisted; automatic resend was suppressed.",
        updated_at: now,
        row_number: raw.row_number,
        work_stage: "alert",
        delivery_mode: "state_only"
      });
      continue;
    }
    const queued = queueAlertState(record, policy, now);
    const existingDeliveryState = ["pending", "retryable_failure"].includes(
      record.alert_status
    );
    if (!existingDeliveryState) continue;
    if (["suppressed", "not_eligible"].includes(queued.alert_status)) {
      selected.push({
        ...queued,
        row_number: raw.row_number,
        work_stage: "alert",
        delivery_mode: "state_only"
      });
      continue;
    }
    if (
      ["pending", "retryable_failure"].includes(queued.alert_status) &&
      retryDue(queued, now) &&
      evaluateAlertEligibility(queued, policy, now).eligible
    ) {
      selected.push({
        ...queued,
        row_number: raw.row_number,
        work_stage: "alert",
        delivery_mode: "deliver"
      });
    }
  }
  selected.sort(
    (left, right) =>
      Number(right.opportunity_score) - Number(left.opportunity_score) ||
      Date.parse(right.posted_at) - Date.parse(left.posted_at) ||
      left.canonical_job_id.localeCompare(right.canonical_job_id)
  );
  return {
    candidates: selected.slice(0, policy.per_run_cap),
    state_updates: []
  };
}

function summaryList(values, policy, fallback) {
  if (!Array.isArray(values) || values.length === 0) return fallback;
  return values
    .slice(0, 3)
    .map((value) =>
      cleanText(
        typeof value === "string"
          ? value
          : value.text || value.summary || value.requirement || "",
        policy.summary_item_characters
      )
    )
    .filter(Boolean)
    .join(" | ") || fallback;
}

function slackEscape(value) {
  return cleanText(value, 500)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;");
}

function fitAlertLines(lines, minimums, maximum) {
  const result = [...lines];
  const length = () =>
    result.reduce((sum, line) => sum + line.length, 0) +
    Math.max(0, result.length - 1);
  while (length() > maximum) {
    let candidate = -1;
    let reducible = 0;
    for (let index = 0; index < result.length; index += 1) {
      const available = result[index].length - minimums[index];
      if (available > reducible) {
        candidate = index;
        reducible = available;
      }
    }
    if (candidate < 0 || reducible <= 0) break;
    const excess = length() - maximum;
    const nextLength =
      result[candidate].length - Math.min(reducible, excess);
    result[candidate] = `${result[candidate]
      .slice(0, Math.max(minimums[candidate] - 1, nextLength - 1))
      .trimEnd()}…`;
  }
  return result.join("\n");
}

function renderAlert(record, policy, { reviewUrl }) {
  const normalizedSourceUrl = normalizeCanonicalUrl(record.canonical_url);
  const sourceUrl =
    normalizedSourceUrl.length <= policy.maximum_action_url_characters
      ? normalizedSourceUrl
      : "";
  let safeReviewUrl = "";
  try {
    const parsed = new URL(reviewUrl);
    if (
      parsed.protocol === "https:" &&
      !parsed.username &&
      !parsed.password &&
      parsed.toString().length <= policy.maximum_action_url_characters
    ) {
      safeReviewUrl = parsed.toString();
    }
  } catch {
    // Configuration validation is surfaced as a terminal delivery failure.
  }
  const age = evaluateAlertEligibility(
    record,
    policy,
    record.alert_last_attempt_at || new Date().toISOString()
  ).posting_age_days;
  const employer = cleanText(record.company, 120) || "Unknown";
  const salary = cleanText(record.salary_text, 120) || "Unknown";
  const instructions = summaryList(
    record.application_instructions,
    policy,
    "None detected"
  );
  const questions = summaryList(
    record.screening_questions,
    policy,
    "None detected"
  );
  const proofs = summaryList(record.selected_proof_refs, policy, "None selected");
  const warnings = summaryList(record.application_warnings, policy, "None");
  const gaps = summaryList(record.requirement_gap_details, policy, "None");
  const links = [
    safeReviewUrl ? `<${safeReviewUrl}|Review in authorized Sheet>` : "Review: unavailable",
    safeReviewUrl ? `<${safeReviewUrl}|Confirm skip in Sheet>` : "Skip: unavailable",
    sourceUrl ? `<${sourceUrl}|Open OnlineJobs.ph>` : "Source: unavailable"
  ].join(" · ");
  const contextLines = [
    `*High-opportunity job:* ${slackEscape(record.job_title) || "Untitled role"}`,
    `Qualification ${record.qualification_score}/100 · Opportunity ${record.opportunity_score}/100 · Confidence ${record.ranking_confidence}`,
    `Employer: ${slackEscape(employer)} · Salary: ${slackEscape(salary)} · Freshness: ${
      Number.isFinite(age) ? `${Math.round(age * 10) / 10} days` : "Unknown"
    }`,
    `Apply Points: ${record.apply_points_recommendation || "Unknown"} · Major gaps: ${slackEscape(gaps)}`,
    `Instructions: ${slackEscape(instructions)}`,
    `Questions: ${slackEscape(questions)}`,
    `Proofs: ${slackEscape(proofs)}`,
    `Warnings: ${slackEscape(warnings)}`
  ];
  const tail = `\n${links}`;
  const text = `${fitAlertLines(
    contextLines,
    [60, 80, 100, 100, 120, 120, 120, 180],
    policy.maximum_message_characters - tail.length
  )}${tail}`;
  return {
    channel: policy.channel,
    idempotency_key: alertIdempotencyKey(record, policy),
    text,
    review_action: {
      mode: "authorized_review_surface",
      url: safeReviewUrl
    },
    skip_action: {
      mode: "review_confirmation",
      url: safeReviewUrl
    },
    source_action: {
      mode: "open_only",
      url: sourceUrl
    }
  };
}

function classifyAlertProviderResult(
  result,
  policy,
  now = new Date().toISOString()
) {
  const status = Number(result?.statusCode || result?.status || 0);
  const message = cleanText(
    result?.error?.message || result?.message || result?.body || "",
    200
  );
  if (result?.configuration_error) {
    return {
      success: false,
      retryable: false,
      category: "configuration_error",
      summary: cleanText(result.configuration_error, 200),
      at: now
    };
  }
  if (status >= 200 && status < 300 && /^(?:ok)?$/i.test(message)) {
    return {
      success: true,
      retryable: false,
      category: "",
      summary: "",
      provider_reference: cleanText(result.provider_reference, 120),
      at: now
    };
  }
  const timeout = status === 0 && /timeout|timed out|aborted/i.test(message);
  if (timeout && policy.retry.ambiguous_timeout_terminal) {
    return {
      success: false,
      retryable: false,
      category: "ambiguous_timeout",
      summary: "Provider timeout has ambiguous delivery; manual reconciliation required.",
      at: now
    };
  }
  const retryable =
    status === 429 ||
    status >= 500 ||
    (status === 0 && /temporar|connection|econn/i.test(message));
  return {
    success: false,
    retryable,
    category:
      status === 429
        ? "rate_limit"
        : status >= 500
          ? "provider_failure"
          : status >= 400
            ? "provider_rejected"
            : "provider_malformed_response",
    summary: message || "Provider response was not a confirmed success.",
    at: now
  };
}

function applyAlertProviderResult(record, result, policy) {
  const outcome = classifyAlertProviderResult(result, policy, result?.at);
  const attempts = Number(record.alert_attempt_count || 0) + 1;
  if (outcome.success) {
    return releaseClaim(
      {
        ...record,
        alert_status: "sent",
        alert_channel: policy.channel,
        alert_policy_version: policy.policy_version,
        alert_idempotency_key: alertIdempotencyKey(record, policy),
        alert_attempt_count: attempts,
        alert_last_attempt_at: outcome.at,
        alert_next_retry_at: "",
        alert_sent_at: outcome.at,
        alert_provider_reference: outcome.provider_reference || "",
        alert_error_category: "",
        alert_error_summary: "",
        alert_suppressed_reason: "",
        updated_at: outcome.at
      },
      record.processing_token,
      outcome.at
    );
  }
  const retryable =
    outcome.retryable && attempts < policy.retry.max_attempts;
  return releaseClaim(
    {
      ...record,
      alert_status: retryable ? "retryable_failure" : "terminal_failure",
      alert_channel: policy.channel,
      alert_policy_version: policy.policy_version,
      alert_idempotency_key: alertIdempotencyKey(record, policy),
      alert_attempt_count: attempts,
      alert_last_attempt_at: outcome.at,
      alert_next_retry_at: retryable
        ? new Date(
            Date.parse(outcome.at) +
              policy.retry.backoff_ms * 2 ** (attempts - 1)
          ).toISOString()
        : "",
      alert_error_category: outcome.category,
      alert_error_summary: cleanText(outcome.summary, 200),
      updated_at: outcome.at
    },
    record.processing_token,
    outcome.at
  );
}


